artifacts.body:
{
  "headline": "Cadence shows a clean revenue driver (117 customers at $500 ARPU, 75% gross margin) but the model needs major structural work before investor diligence — no CAC, no scenarios, flat expenses, and ~12.5 months of stated runway put significant pressure on the raise timeline.",
  "investor_talking_points": [
    "Our gross margin is 75%, which is at the strong end of B2B SaaS benchmarks — COGS is well-controlled as we scale.",
    "We're growing customer count at 8% month-over-month from a clean, driver-based revenue model with explicit churn modeling at 3% monthly.",
    "We have $1.5M cash as of June 2026 and are actively working to extend runway by adding a downside scenario and tightening our hiring plan before we go to market."
  ],
  "lenses": {
    "runway": {
      "callout": "Stated runway is ~12.5 months ($1.5M ÷ $120K burn), with stress scenarios narrowing to 10 months (crisis) and 13 months (slow-growth) — all below the 18-month seed benchmark.",
      "highlight": "The base runway scenario shows the business as default-alive on the current trajectory, but there is a material reconciliation gap: the extracted expense base ($80K OpEx + $12.5K COGS - $58.5K revenue ≈ $34K net) does not match the stated $120K burn — meaning actual burn is likely higher than the model reflects.",
      "watch_out": "With no scenario modeling and flat expenses against 8% monthly revenue growth, the model cannot demonstrate how burn evolves — investors will build their own (more conservative) version."
    },
    "unit_economics": {
      "callout": "Gross margin of 75% is strong (KeyBanc 2024 benchmark: ≥75% for strong). LTV is calculable at ~$12,500 per customer (ARPU $500 ÷ 3% churn × 75% GM), but CAC is completely absent — LTV/CAC and payback period cannot be computed.",
      "watch_out": "3% monthly churn (~31% annually) is well above the B2B SaaS benchmark of <5–8% annually, and with no expansion revenue modeled, NRR sits at approximately 97%. Both issues will surface in investor diligence."
    }
  }
}

